"""Derive SkyyTrees/build_skyytrees_0.6.7.py from SkyyTrees 0.6.6 (build_skyytrees_0.6.6.py = the SET pin, itself GENERATED by
tools/trees_0_6_6_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.6 (tools/soundpass_gen.Patch).
Run:
    python tools/trees_0_6_7_patch.py && python SkyyTrees/build_skyytrees_0.6.7.py && python SkyyTrees/test_skyytrees_0.6.7.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.7 (2026-10-30) = WEAPONCRAFT x1.5 TEXT + TABLE TIDY (Skyy 2026-10-30 "work through your whole list"; no Java change but the version).
  1. ACCESSORY PLATES TEXT (Weaponcraft branch 2 row 4, Combat.b2.r4a): the /tree page said +0.5 % max Health a rank per counting accessory;
     SkyyAccessories 0.5.33 (live) gives +0.75 % (3 ranks x 5 accessories = 11.25 %; the Weaponcraft max Health budget 13.75 % with
     Toughness) - Skyy's 2026-10-27 popup answer "Raise cap to 13.75%" (docs/answered/classes.md). tools/trees_v3_data.py R062_TEXT now holds
     the new text (r062_apply). Every other Weaponcraft row text was compared with tools/wc15.py ROWS + the effects table: already right.
  2. THE EFFECTS TABLE IS THE ONE SOURCE: tools/trees_v3_effects.py EFFECTS holds the 14 wc15 rows' NEW numbers (SkyyGear 5, SkyyMobs 5,
     SkyyClasses 3, SkyyAccessories 1); tools/wc15.py apply() now swaps nothing and only adds its marker. SkyyTrees reads none of those
     rows' numbers (only their keys), so this jar's Java is unchanged by it; asserted below that the table holds every wc15 NEW number.
  3. VERIFIED (no change): tree:<uuid> lists ",Beastmastery:<spent>/<points>" (0.6.2, SkyyMenu's Right now); Warm Nest / Burrow Nursery
     (Skill.Beastmastery.b3.r2c / b2.r4c) are sold while SkyyPets lists them in tree:reads:SkyyPets (SkyyPets 0.4.17+ applies them).
  SAVED DATA: none. ROLLBACK to 0.6.6: alone (the Accessory Plates text says +0.5 % again; numbers come from SkyyAccessories either way).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.6.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.7.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.6"') and P.has("0.6.6 (2026-10-27) = WIDE SOWING IN CREATIVE") and not P.has("0.6.7 (2026-10-30)"), "not the generated SkyyTrees 0.6.6 script"
REG0, SYS0, CLS0, M0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass("), P.s.count("\nM(")

P.rep('''"""SkyyTrees 0.6.6 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_6_patch.py from build_skyytrees_0.6.5.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.7 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_7_patch.py from build_skyytrees_0.6.6.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.6 - GENERATED by tools/trees_0_6_6_patch.py from build_skyytrees_0.6.5.py:
''')
P.rep('VERSION = "0.6.6"', 'VERSION = "0.6.7"')

# build-time guards: the new Accessory Plates text reached every tree that shows the row, no old text is left, and the shared effects table
# holds every wc15 NEW number (the one source) - SkyyTrees itself reads only the rows' keys
P.rep('''assert V3D.R063_APPLIED and V3D.R064_APPLIED
''', '''assert V3D.R063_APPLIED and V3D.R064_APPLIED
_AP067 = [_u["text"] for _t in V3D.TREES for _b in _t["branches"] for _r in _b["rows"] for _u in _r["ups"] if _u["name"] == "Accessory Plates"]
assert _AP067 and set(_AP067) == {"+0.75% max Health/rank per counting accessory (max 5)"}, ("0.6.7: the Accessory Plates text", _AP067)
assert not [_u for _t in V3D.TREES for _b in _t["branches"] for _r in _b["rows"] for _u in _r["ups"] if "+0.5% max Health/rank per counting" in _u["text"]]
print("0.6.7 Accessory Plates text: %d trees say +0.75 %% a rank" % len(_AP067))
''')
P.rep('''assert [(_e[2], _e[4]) for _e in V3E.EFFECTS[-2:]] == [("r2c", "hatchspd"), ("r4c", "hatch")], "0.6.2: the hatching rows"
''', '''assert [(_e[2], _e[4]) for _e in V3E.EFFECTS[-2:]] == [("r2c", "hatchspd"), ("r4c", "hatch")], "0.6.2: the hatching rows"
import wc15 as _WC15   # 0.6.7: tools/trees_v3_effects.py EFFECTS holds the wc15 NEW numbers itself (the one source; wc15.apply swaps nothing now)
for _m, _rs in _WC15.ROWS.items():
    for _r in _rs:
        _h = [_e for _e in V3E.EFFECTS if (_e[0], _e[1], _e[2], _e[4]) == _r[:4]]
        assert len(_h) == 1 and _h[0][3] == _m and abs(_h[0][5] - _r[5]) < 1e-12, ("0.6.7: the effects table holds the wc15 number", _m, _r, _h)
del _m, _rs, _r, _h
''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0 and P.s.count("\nM(") == M0, "0.6.7: no new class / system / command / method"
P.finish()
print("wrote", P.dst)
